def graph(title,xmin,xmax,ymin,ymax,segments,closed=None,opened=None,xt=None,yt=None):
 return {'type':'source-function-graph','title':title,'xMin':xmin,'xMax':xmax,'yMin':ymin,'yMax':ymax,'linearSegments':segments,'closedPoints':closed or [],'openPoints':opened or [],'xTicks':xt or [],'yTicks':yt or []}
def curve(a,b,fn):
 xs=[a+(b-a)*i/60 for i in range(61)]
 return [[x,fn(x),z,fn(z)] for x,z in zip(xs,xs[1:])]
def diagram(g,caption):return {'type':'diagram','diagram':g,'caption':caption}
